888	export const makeCharRule = (
889	  ruleDef: InternalRuleDefChar | InternalRuleDefCharNot
890	): RuleChar | RuleCharExclude => {
891	  const value = ruleDef.value as (number | Range)[];
892	  if (isRuleDefCharNot(ruleDef)) {
893	    return new RuleCharExclude(value);
894	  }
895	  if (isRuleDefChar(ruleDef)) {
