902	export const buildRuleStack = (
903	  linearRules: InternalRuleDef[]
904	): UnresolvedRule[][] => {
905	  let paths: UnresolvedRule[] = [];
906	  const stack: UnresolvedRule[][] = [];
907	  let idx = 0;
908	
909	  while (idx < linearRules.length) {
910	    const ruleDef = linearRules[idx];
911	    if (isRuleDefChar(ruleDef) || isRuleDefCharNot(ruleDef)) {
912	      // this could be a single char, or a range, or a sequence of alts; we don't know until we step through it.
913	      const charRule = makeCharRule(ruleDef);
914	      idx += 1;
915	      let rule: InternalRuleDef | null =
916	        idx < linearRules.length ? linearRules[idx] : null;
917	      while (
918	        idx < linearRules.length &&
919	        (isRuleDefCharRngUpper(rule) || isRuleDefCharAlt(rule))
920	      ) {
921	        if (isRuleDefCharRngUpper(rule)) {
922	          // previous rule value should be a number
923	          const prevValue = charRule.value.pop();
924	          if (isRange(prevValue)) {
925	            throw new Error(
926	              `Unexpected range, expected a number but got an array: ${JSON.stringify(
927	                prevValue
928	              )}`
929	            );
930	          }
931	          if (prevValue === undefined) {
932	            throw new Error('Unexpected undefined value');
933	          }
934	
935	          charRule.value.push([prevValue, rule.value] as Range);
936	        }
937	        if (isRuleDefCharAlt(rule)) {
938	          charRule.value.push(rule.value);
939	        }
940	        idx += 1;
941	        rule = idx < linearRules.length ? linearRules[idx] : null;
942	      }
943	      paths.push(charRule);
944	    } else {
945	      if (isRuleDefAlt(ruleDef)) {
946	        if (paths.length === 0) {
947	          throw new Error('Encountered alt without anything before it');
948	        }
949	        paths.push(new RuleEnd());
950	        stack.push(paths);
951	        paths = [];
952	      } else if (isRuleDefEnd(ruleDef)) {
953	        paths.push(new RuleEnd());
954	      } else if (isRuleDefRef(ruleDef)) {
955	        paths.push(new RuleRef(ruleDef.value));
956	      } else if (isRuleDefCharAlt(ruleDef)) {
957	        throw new Error(
958	          `Encountered char alt, should be handled by above block: ${ruleDef}`
959	        );
960	      } else {
961	        throw new Error(`Unsupported rule type: ${ruleDef}`);
962	      }
963	      idx += 1;
964	    }
965	  }
966	
967	  if (!isRuleEnd(paths[paths.length - 1])) {
968	    paths.push(new RuleEnd());
969	  }
970	
971	  stack.push(paths);
972	  return stack;
973	};
