1001	const ESCAPED_CONTROL_CHARS: Record<string, number> = {
1002	  t: 9,
1003	  r: 13,
1004	  n: 10,
1005	};
1006	
1007	const ESCAPED_LITERAL_CHARS = ['"', '[', ']', '\\'];
