1009	export const parseChar = (src: string, pos: number): [number, number] => {
1010	  if (pos >= src.length) {
1011	    throw new GrammarParseError(
1012	      src,
1013	      pos,
1014	      'Unexpected end of grammar input, failed to complete parse'
1015	    );
1016	  }
1017	
1018	  if (src[pos] === '\\') {
1019	    const next = src[pos + 1];
1020	    if (next === 'x') {
1021	      return [parseInt(src.slice(pos + 2, pos + 4), 16), 4];
1022	    }
1023	    if (next === 'u') {
1024	      return [parseInt(src.slice(pos + 2, pos + 6), 16), 6];
1025	    }
1026	    if (next === 'U') {
1027	      return [parseInt(src.slice(pos + 2, pos + 10), 16), 10];
1028	    }
1029	    if (next in ESCAPED_CONTROL_CHARS) {
1030	      return [ESCAPED_CONTROL_CHARS[next], 2];
1031	    }
1032	    if (ESCAPED_LITERAL_CHARS.includes(next)) {
1033	      return [next.codePointAt(0) as number, 2];
1034	    }
1035	    throw new GrammarParseError(src, pos, `Unknown escape at ${src[pos]}`);
1036	  }
1037	
1038	  return [src.codePointAt(pos) as number, 1];
1039	};
