    if is_rule_char_exclude(rule):
        return f"{KEY_TRANSLATION.RuleCharExclude}-{_serialize_value(rule.value)}"

    if is_rule_ref(rule):
        return f"{KEY_TRANSLATION.RuleRef}-{rule.value}"

    raise ValueError(f"Unknown rule type: {rule}")

