                self.src, self.pos, f"Duration of {self.time_limit} exceeded"
            )

    def parse_sequence(self, rule_name: str, out_elements: List, depth: int = 0) -> None:
        is_nested = depth != 0
        src = self.src
        last_sym_start = len(out_elements)

        while self.pos < len(src):
